import React, { PropsWithChildren } from 'react';
import styled from 'styled-components';

import { useMeterBarLayoutSize } from '../../../context/MeterBarLayoutSize.context.js';
import { getChartElementsSizes } from '../../../functions/get-chart-elements-sizes.js';

const StyledIconWrapper = /* @__PURE__ */ styled('div')<{ $size: number }>(
  ({ $size }) => ({
    width: `${$size}px`,
    height: `${$size}px`,
    fontSize: `${$size}px`,
    textAlign: 'center',
    position: 'relative',
    lineHeight: `${$size}px`,

    '& svg': {
      position: 'absolute',
      width: `${$size}px`,
      height: `${$size}px`,
      top: '50%',
      transform: 'translate(-50%,-50%)',
    },
  }),
);

export const Icon = ({ children }: PropsWithChildren) => {
  const { size } = useMeterBarLayoutSize();
  const { icon: iconWrapperSize } = getChartElementsSizes(size);

  return children !== undefined ? (
    <StyledIconWrapper $size={iconWrapperSize}>{children}</StyledIconWrapper>
  ) : null;
};

Icon['displayName'] = 'MeterBarLayout.Icon';
